const customizableCard=cardHTML;
cardHTML=function(c,m=null,full=false){
 const box=document.createElement('div');box.innerHTML=customizableCard(c,m,full);const card=box.firstElementChild,p=Loyalty.program(c),en=c.cardLanguage==='en',num=n=>Number(n).toLocaleString(en?'en-US':'ar-SA'),member=m||{stamps:2,points:20,rewards:0,name:en?'Card preview':'معاينة البطاقة',id:'RJ-PREVIEW01'},balance=p.type==='points'?(member.points||0):(member.stamps||0),goal=p.type==='points'?p.pointsCost:c.target,ready=Loyalty.available(member,c),remaining=Math.max(0,goal-balance);
 card.dir=en?'ltr':'rtl';card.lang=en?'en':'ar';card.classList.add(en?'card-english':'card-arabic',`balance-${c.balanceStyle||'plain'}`);card.classList.toggle('balance-hidden',c.hideBalance===true);
 const heading=card.querySelector('.studio-heading');heading.style.transform=`translate(${c.headlineX||0}px,${c.headlineY||0}px)`;
 const title=heading.querySelector('h3'),eyebrow=heading.querySelector('span'),program=heading.querySelector('p');title.textContent=c.headline||'';title.hidden=c.showHeadline!==true||!c.headline;eyebrow.textContent=c.eyebrow||'';eyebrow.hidden=!c.eyebrow;program.textContent=en?{visits:'Visits card',discount:'Discount card',points:'Points card'}[p.type]:{visits:'بطاقة الزيارات',discount:'بطاقة الخصومات',points:'بطاقة النقاط'}[p.type];program.hidden=c.showProgramLabel===false;heading.hidden=title.hidden&&eyebrow.hidden&&program.hidden;
 const counter=card.querySelector('.studio-balance');counter.style.transform=`translate(${c.balanceX||0}px,${c.balanceY||0}px)`;counter.querySelector('b').textContent=num(balance);counter.querySelector('span').innerHTML=`${en?(p.type==='points'?'points':'visits'):(p.type==='points'?'نقطة':'زيارة')} <small>/ ${num(goal)}</small>`;
 if(c.balanceStyle==='progress')counter.insertAdjacentHTML('beforeend',`<div class="balance-meter" role="progressbar" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(goal,balance)}"><i style="width:${Math.min(100,balance/goal*100)}%"></i></div>`);
 const reward=card.querySelector('.studio-reward'),label=p.type==='discount'?(en?`Discount ${p.discountValue}${p.discountType==='percent'?'%':' SAR'}`:Loyalty.label(c)):(en?(c.rewardEnglish||c.reward):c.reward);const rewardIcon=c.rewardImage?`<img class="reward-custom-image" src="${esc(c.rewardImage)}" alt="${en?'Reward':'المكافأة'}">`:icon('gift');reward.innerHTML=`<div class="reward-art" style="--reward-size:${c.rewardImageSize||24}px;transform:translate(${c.rewardX||0}px,${c.rewardY||0}px)">${rewardIcon}</div><span>${ready?(en?`${num(ready)} reward${ready===1?'':'s'} ready`:`${num(ready)} مكافأة جاهزة`):esc(label)}<small>${ready?(en?'Thank you for coming back':'شكرًا لرجعتك'):en?`${num(remaining)} ${p.type==='points'?'points':'visits'} to your reward`:`${num(remaining)} ${p.type==='points'?'نقطة':'زيارات'} للمكافأة`}</small></span>`;
 const logo=card.querySelector('.studio-logo');if(logo){logo.style.transform=`translate(${c.logoX||0}px,${c.logoY||0}px)`;logo.style.width=(c.logoSize||58)+'px';logo.style.height=(c.logoSize||58)+'px';}
 if(en){const category=card.querySelector('.studio-identity small');if(category)category.textContent=({'كافيه':'Cafe','مغسلة سيارات':'Car wash','حلاق':'Barbershop','صالون':'Salon','متجر':'Store','مطعم':'Restaurant','نشاط آخر':'Business'})[c.category]||c.category;card.querySelectorAll('.studio-stamp').forEach(el=>el.title=el.classList.contains('earned')?'Completed':'Upcoming');card.querySelector('.studio-stamps')?.setAttribute('aria-label',`${num(balance)} of ${num(goal)}`);const memberLabel=card.querySelector('.studio-member');if(memberLabel&&!m)memberLabel.textContent='Card preview · RJ-PREVIEW01';const expand=card.querySelector('.card-code-expand');if(expand)expand.textContent='Show full code';}
 return box.innerHTML;
};
const customDesign=designHTML;
const cardOption=(key,label,value,type='text')=>`<label class="field"><span>${label}</span><input class="input" type="${type}" data-enhance="${key}" value="${esc(value??'')}" ${type==='text'?'maxlength="100"':''}></label>`;
const cardToggle=(key,label,value)=>`<label class="studio-toggle"><input type="checkbox" data-enhance="${key}" ${value?'checked':''}> ${label}</label>`;
const offsetControl=(key,label,value,min=-60,max=60)=>`<label class="field"><span>${label}</span><input type="range" data-enhance="${key}" aria-label="${label}" value="${value??0}" min="${min}" max="${max}"></label>`;
designHTML=function(){const box=document.createElement('div');box.innerHTML=customDesign();const tools=box.querySelector('.studio-tools');
 tools.hidden=true; tools.innerHTML='';
 const section=box.querySelector('.studio-controls');section.insertAdjacentHTML('afterbegin',`<details class="card-option-panel"><summary>اللغة والنصوص</summary><label class="field"><span>لغة البطاقة</span><select data-enhance="cardLanguage"><option value="ar" ${draft.cardLanguage!=='en'?'selected':''}>العربية</option><option value="en" ${draft.cardLanguage==='en'?'selected':''}>English</option></select></label><p class="line-meta">لغة العناوين والعداد والمكافأة. اكتب اسم النشاط والنصوص الخاصة باللغة التي تريدها.</p>${cardToggle('showHeadline','إظهار عبارة مخصصة',draft.showHeadline===true)}${cardOption('headline','العبارة على البطاقة · اتركها فارغة إن لم ترغب بها',draft.headline)}${cardOption('eyebrow','سطر صغير أعلى العبارة · اختياري',draft.eyebrow)}${cardToggle('showProgramLabel','إظهار نوع برنامج الولاء',draft.showProgramLabel!==false)}${cardOption('rewardEnglish','اسم المكافأة بالإنجليزية · اختياري',draft.rewardEnglish)}</details><details class="card-option-panel"><summary>طريقة عرض الزيارات والنقاط</summary>${cardToggle('hideBalance','إخفاء عداد الرصيد',draft.hideBalance===true)}<label class="field"><span>مظهر العداد</span><select data-enhance="balanceStyle">${[['plain','شفاف بلا خلفية'],['glass','زجاجي شفاف'],['solid','خلفية داكنة'],['pill','كبسولة'],['outline','إطار خفيف'],['neon','توهج'],['progress','عداد مع شريط تقدم']].map(([id,label])=>`<option value="${id}" ${draft.balanceStyle===id?'selected':''}>${label}</option>`).join('')}</select></label><p class="line-meta">الرصيد والعدد المتبقي يحتسبان تلقائيًا من برنامج الولاء؛ التصميم لا يغيّر الاستحقاق.</p>${offsetControl('balanceX','مكان العداد أفقيًا',draft.balanceX)}${offsetControl('balanceY','مكان العداد رأسيًا',draft.balanceY,-30,60)}</details><details class="card-option-panel"><summary>صورة المكافأة</summary>${mediaField('rewardImage','reward-image-file','صورة المكافأة بدل علامة الهدية')}${offsetControl('rewardImageSize','حجم صورة المكافأة',draft.rewardImageSize??24,20,80)}${offsetControl('rewardX','مكان صورة المكافأة أفقيًا',draft.rewardX)}${offsetControl('rewardY','مكان صورة المكافأة رأسيًا',draft.rewardY,-30,30)}</details><details class="card-option-panel"><summary>ترتيب الشعار والنص</summary>${offsetControl('logoSize','حجم الشعار',draft.logoSize??58,32,100)}${offsetControl('logoX','مكان الشعار أفقيًا',draft.logoX)}${offsetControl('logoY','مكان الشعار رأسيًا',draft.logoY,-30,60)}${offsetControl('headlineX','مكان العبارة أفقيًا',draft.headlineX)}${offsetControl('headlineY','مكان العبارة رأسيًا',draft.headlineY,-30,60)}<button class="btn secondary full" data-action="reset-card-arrangement">إعادة ترتيب كل العناصر</button><p class="line-meta">يعيد أماكن الأكواب والشعار والعبارة والعداد وصورة المكافأة؛ يحافظ على الصور والنصوص وقواعد البرنامج.</p></details>`);return box.innerHTML;};
const customMedia=refreshMedia;
refreshMedia=function(){customMedia();const el=document.getElementById('media-rewardImage'),input=document.getElementById('reward-image-file');if(!draft.rewardImage&&input){input.value='';input.dataset.generation='removed';}if(el)el.innerHTML=draft.rewardImage?`<div class="uploaded-image"><img src="${esc(draft.rewardImage)}" alt="صورة المكافأة"><button class="image-remove" data-action="media-remove" data-key="rewardImage" aria-label="إزالة صورة المكافأة">×</button></div>`:'<p class="line-meta">نستخدم علامة الهدية الافتراضية.</p>';};
const customBind=bindEditor;
bindEditor=function(){customBind();document.querySelectorAll('[data-enhance]').forEach(el=>el.addEventListener('input',()=>{draft[el.dataset.enhance]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;const options=document.getElementById('decoration-options');if(options)options.hidden=draft.effectsEnabled!==true;updatePreview();}));const input=document.getElementById('reward-image-file');input?.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5242880){toast('اختر صورة PNG أو JPG أو WebP حتى ٥ ميجابايت.');input.value='';return;}const generation=crypto.randomUUID();input.dataset.generation=generation;try{const value=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=new Image();img.src=value;await img.decode();if(!input.isConnected||input.dataset.generation!==generation)return;draft.rewardImage=value;updatePreview();}catch{toast('الصورة غير قابلة للعرض.');}});};
mutationActions.add('choose-decoration');mutationActions.add('reset-card-arrangement');
window.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['choose-decoration','reset-card-arrangement'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();if(!canOperate())return toast('يلزم تفعيل الاشتراك.');if(b.dataset.action==='choose-decoration'){draft.decoration=b.dataset.decoration;document.querySelectorAll('.decoration-choice').forEach(el=>el.classList.toggle('selected',el===b));updatePreview();}else{for(const key of ['elementLayout','stampX','stampY','stampSize','logoX','logoY','logoSize','rewardX','rewardY','rewardImageSize','headlineX','headlineY','balanceX','balanceY'])delete draft[key];render();toast('تمت إعادة ترتيب كل العناصر.');}},true);
const optionsPreview=updatePreview;updatePreview=function(){optionsPreview();const selector=document.getElementById('studio-item-select');if(selector&&selector.options.length!==draft.target){const selected=Math.min(Number(selector.value)||0,draft.target-1);selector.innerHTML=Array.from({length:draft.target},(_,i)=>`<option value="${i}">العنصر ${fmt(i+1)}</option>`).join('');selector.value=String(selected);selector.dispatchEvent(new Event('change'));}};
render();
